{
  "name": "@askjo/camofox-browser",
  "version": "1.14.0",
  "description": "Headless browser automation server and OpenClaw plugin for AI agents - anti-detection, element refs, and session isolation",
  "type": "module",
  "main": "server.js",
  "license": "MIT",
  "author": "Jo Inc <oss@askjo.ai>",
  "homepage": "https://github.com/jo-inc/camofox-browser#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jo-inc/camofox-browser.git"
  },
  "bugs": {
    "url": "https://github.com/jo-inc/camofox-browser/issues"
  },
  "keywords": [
    "browser",
    "automation",
    "headless",
    "scraping",
    "camofox",
    "camoufox",
    "anti-detection",
    "ai-agent",
    "openclaw",
    "clawdbot",
    "moltbot",
    "playwright",
    "firefox",
    "youtube",
    "transcript"
  ],
  "engines": {
    "node": ">=22"
  },
  "files": [
    "server.js",
    "lib/",
    "plugins/",
    "camofox.config.json",
    "plugin.ts",
    "plugin.js",
    "dist/plugin.js",
    "tsconfig.json",
    "openclaw.plugin.json",
    "mcp/",
    "bin/",
    "scripts/",
    "run.sh",
    "Dockerfile",
    "README.md",
    "LICENSE",
    "AGENTS.md",
    "!**/*.test.js",
    "!**/*.test.ts",
    "!**/*.spec.js"
  ],
  "openclaw": {
    "extensions": [
      "plugin.ts"
    ],
    "runtimeExtensions": [
      "plugin.js"
    ],
    "compat": {
      "pluginApi": ">=2026.3.24-beta.2"
    },
    "build": {
      "openclawVersion": "2026.5.3"
    },
    "tools": [
      {
        "name": "camofox_create_tab",
        "description": "Open a new browser tab at a URL"
      },
      {
        "name": "camofox_snapshot",
        "description": "Get accessibility snapshot with element refs"
      },
      {
        "name": "camofox_click",
        "description": "Click an element by ref or CSS selector"
      },
      {
        "name": "camofox_type",
        "description": "Type text into an element"
      },
      {
        "name": "camofox_navigate",
        "description": "Navigate to URL or search macro"
      },
      {
        "name": "camofox_scroll",
        "description": "Scroll page up/down/left/right"
      },
      {
        "name": "camofox_screenshot",
        "description": "Capture page screenshot"
      },
      {
        "name": "camofox_close_tab",
        "description": "Close a browser tab"
      },
      {
        "name": "camofox_evaluate",
        "description": "Execute JavaScript in a Camoufox tab page context"
      },
      {
        "name": "camofox_list_tabs",
        "description": "List open tabs for a user"
      },
      {
        "name": "camofox_import_cookies",
        "description": "Import Netscape cookie file (requires CAMOFOX_API_KEY)"
      }
    ]
  },
  "scripts": {
    "build": "tsc -p . || true; mkdir -p dist && cp plugin.js dist/plugin.js",
    "prepublishOnly": "npm run build",
    "start": "node server.js",
    "mcp": "node mcp/server.mjs",
    "test:mcp": "npm ci --prefix mcp && node scripts/test-mcp.mjs && node scripts/test-mcp-package.mjs",
    "test:unit": "NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit tests/unit",
    "test": "npm run test:unit && npm run test:e2e && npm run test:plugins",
    "test:e2e": "NODE_OPTIONS='--experimental-vm-modules' jest --config jest.config.e2e.cjs --runInBand --forceExit",
    "test:plugins": "NODE_OPTIONS='--experimental-vm-modules' jest --forceExit plugins/",
    "test:live": "RUN_LIVE_TESTS=1 NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit tests/live",
    "test:debug": "DEBUG_SERVER=1 NODE_OPTIONS='--experimental-vm-modules' jest --runInBand --forceExit",
    "plugin": "node scripts/plugin.js",
    "generate-openapi": "node scripts/generate-openapi.js",
    "version:sync": "node scripts/sync-version.js",
    "version": "node scripts/sync-version.js && node scripts/generate-openapi.js && git add openclaw.plugin.json mcp/package.json mcp/package-lock.json openapi.json",
    "postinstall": "node scripts/postinstall.js",
    "fetch-bin": "npx camoufox-js fetch"
  },
  "dependencies": {
    "better-sqlite3": "13.0.1",
    "camoufox-js": "0.11.5",
    "express": "^5.2.1",
    "playwright-core": "^1.58.0",
    "prom-client": "^15.1.3",
    "swagger-jsdoc": "^6.2.8"
  },
  "optionalDependencies": {
    "@modelcontextprotocol/sdk": "^1.30.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "jest": "^30.4.2",
    "pngjs": "^7.0.0",
    "typescript": "^5.7.0"
  },
  "overrides": {
    "@jest/reporters": {
      "glob": "13.0.6"
    },
    "babel-plugin-istanbul": {
      "test-exclude": "8.0.0"
    },
    "jest-config": {
      "glob": "13.0.6"
    },
    "jest-runtime": {
      "glob": "13.0.6"
    },
    "swagger-jsdoc": {
      "glob": "13.0.6"
    }
  },
  "bin": {
    "camofox-browser": "./bin/camofox-browser.js",
    "camofox-browser-mcp": "./mcp/server.mjs"
  }
}

[package]
name = "memvid-core"
version = "2.0.140"
edition = "2024"
rust-version = "1.85.0"
license = "Apache-2.0"
description = "Core library for Memvid v2, a crash-safe, deterministic, single-file AI memory."
repository = "https://github.com/memvid/memvid"
documentation = "https://docs.memvid.com"
readme = "README.md"
keywords = ["ai", "memory", "search", "vector", "embeddings"]
categories = ["database", "data-structures"]
include = ["src/**/*", "data/**/*", "Cargo.toml", "README.md"]

[dependencies]
once_cell = "1.19.0"
serde = { version = "1.0.228", features = ["derive"] }
bincode = { version = "2.0.1", features = ["serde"] }
blake3 = "1.5.1"
uuid = { version = "1.10.0", features = ["v4", "serde"] }
log = "0.4.22"
thiserror = "2.0.17"
fs2 = "0.4.3"
zstd = "0.13.1"
lz4_flex = "0.12.0"
tracing = "0.1.41"
serde_json = "1.0.145"
ed25519-dalek = { version = "2.2.0", features = ["std"] }
base64 = "0.22.1"
sha2 = "0.10.9"
hex = "0.4.3"
# extractous uses GraalVM native compilation which doesn't work on Windows ARM or WSL2 on ARM
# Enable with --features extractous for full document extraction (PDF, DOCX, etc.)
extractous = { version = "0.3", optional = true }
regex = "1.11.1"
time = { version = "0.3.36", features = ["formatting", "parsing"] }
chrono = { version = "0.4.42", features = ["serde"] }
interim = { version = "0.2.1", optional = true }
lopdf = "0.39"
# Pure Rust PDF text extraction - used as primary extractor when extractous is disabled
pdf-extract = { version = "0.10", optional = true }
# High-accuracy PDF text extraction with perfect word spacing (2025)
pdf_oxide = { version = "0.3", optional = true }
unicode-normalization = "0.1"
unicode-segmentation = "1.11"
zip = { version = "7.1", default-features = false, features = ["deflate"] }
quick-xml = "0.31"
calamine = "0.22"
pdfium-render = { version = "0.8.28", optional = true }
tempfile = "3.10.1"
num_cpus = { version = "1.17", optional = true }
crossbeam-channel = { version = "0.5.13", optional = true }
memmap2 = "0.9"
memchr = "2.7"
same-file = "1.0"
fs-err = "3.2"
atomic-write-file = "0.3"
dirs-next = "2.0"
smallvec = { version = "1.13", features = ["serde", "union", "const_generics", "write"] }
tantivy = { version = "0.25.0", optional = true, default-features = false, features = ["mmap"] }
ort = { version = "=2.0.0-rc.10", optional = true }
hnsw = { version = "0.11.0", optional = true, features = ["serde"] }
jsonwebtoken = { version = "10.0.0", optional = true, features = ["rust_crypto"] }
image = { version = "0.25", optional = true, default-features = false, features = ["jpeg", "png", "webp"] }
ndarray = { version = "0.16", optional = true }
rayon = { version = "1.10", optional = true }
tokenizers = { version = "0.22", optional = true }
symphonia = { version = "0.5.3", optional = true, default-features = false, features = ["aac", "mp3", "flac", "isomp4", "ogg", "wav", "pcm"] }
rubato = { version = "0.15", optional = true }
rustfft = { version = "6.2", optional = true }

# Encryption capsules (.mv2e) - feature-gated
argon2 = { version = "0.5", optional = true }
aes-gcm = { version = "0.10", optional = true }
rand = { version = "0.8", optional = true, features = ["serde1"] }
rand_pcg = { version = "0.3", optional = true, features = ["serde1"] }
zeroize = { version = "1.7", optional = true }

# Candle ML framework for Whisper transcription
candle-core = { version = "0.9", optional = true }
candle-nn = { version = "0.9", optional = true }
candle-transformers = { version = "0.9", optional = true }
hf-hub = { version = "0.4", optional = true, features = ["tokio"] }
byteorder = { version = "1.5", optional = true }

# SymSpell for PDF text cleanup - fixes broken word spacing from PDF extraction
symspell = { version = "0.4", optional = true }
# SIMD acceleration for vector distance calculations
wide = { version = "1.1", optional = true }
space = { version = "0.17", optional = true }

# HTTP client for API-based embedding providers (OpenAI, etc.)
reqwest = { version = "0.12", optional = true, default-features = false, features = ["blocking", "json", "rustls-tls"] }

# Platform-specific: libc for stderr suppression on macOS
[target.'cfg(target_os = "macos")'.dependencies]
libc = "0.2"

[features]
default = ["lex", "pdf_extract", "simd"]
# pdf_oxide disabled - cff-parser panics on ligature fonts (uniFB01/uniFB02)
# symspell_cleanup - enables robust PDF text repair (requires `make download-models` for dictionaries)
lex = ["dep:tantivy"]
extractous = ["dep:extractous"]
# Pure Rust PDF extraction - faster than lopdf for text extraction, cross-platform
pdf_extract = ["dep:pdf-extract"]
# High-accuracy PDF extraction with perfect word spacing (recommended for 2025+)
pdf_oxide = ["dep:pdf_oxide"]
vec = ["dep:ort", "dep:hnsw", "dep:ndarray", "dep:tokenizers", "dep:space", "dep:rand", "dep:rand_pcg"]
clip = ["vec", "dep:image", "dep:ndarray", "dep:rayon", "dep:tokenizers"]
mmap = []
pdfium = ["dep:pdfium-render"]
temporal_track = []
temporal_enrich = ["dep:interim"]
p

{
  "type": "module",
  "scripts": {
    "test": "npx ava tests/*.test.js",
    "check:reserved-order": "node util/check-reserved-order.cjs",
    "add:reserved": "node util/add-reserved-subdomain.cjs"
  },
  "devDependencies": {
    "ava": "^8.0.1",
    "fs-extra": "^11.4.0",
    "prettier": "3.9.6"
  }
}
